using System.Collections.Generic;
using System.IO;
using System.Text.Json;
using HuntingLogHelper.Core;

namespace HuntingLogHelper.Data;

/// <summary>Loads targets generated by tools/build_targets.py, embedded in the DLL from Data/*.json.</summary>
public sealed class JsonTargetDatabase : ITargetDatabase
{
    private readonly Dictionary<LogKind, List<HuntTarget>> targets = new();

    public JsonTargetDatabase()
    {
        targets[LogKind.Class] = Load("class_targets.json");
        targets[LogKind.GrandCompany] = Load("gc_targets.json");
        Plugin.Log.Information($"Loaded {targets[LogKind.Class].Count} class and {targets[LogKind.GrandCompany].Count} GC targets.");
    }

    public IReadOnlyList<HuntTarget> All(LogKind kind) => targets[kind];

    private static List<HuntTarget> Load(string file)
    {
        var name = $"HuntingLogHelper.Data.{file}";
        using var stream = typeof(JsonTargetDatabase).Assembly.GetManifestResourceStream(name);
        if (stream == null)
        {
            Plugin.Log.Warning($"Embedded target data missing: {name}");
            return new();
        }
        var options = new JsonSerializerOptions { PropertyNameCaseInsensitive = true };
        return JsonSerializer.Deserialize<List<HuntTarget>>(stream, options) ?? new();
    }
}
